$ErrorActionPreference='Stop'
$runRoot='C:\Users\suanr\genesis-vector-memory-followup-20261031\query-reopen-bge-candidate-trace-20261031T145352'
$configPath=Join-Path $runRoot 'run-config.json'
$driverPath=Join-Path $runRoot 'spawn-benchmark.py'
$config=Get-Content -LiteralPath $configPath -Raw|ConvertFrom-Json
$envKeys=@($config.env_whitelist.PSObject.Properties.Name)
if($envKeys.Count -ne 16){throw "Expected full 16-key environment, found $($envKeys.Count)"}
if($config.env_whitelist.GB_MEMORY_AUDIT -ne '1' -or $config.env_whitelist.GB_MEMORY_OPEN_REPEAT -ne '1' -or $config.env_whitelist.GB_MEMORY_INPUT -ne $config.input_dir){throw 'Audit dispatch or fresh-child environment mismatch'}
if($null -ne $config.env_whitelist.GB_MEMORY_OPEN_ONLY -or $null -ne $config.env_whitelist.GB_MEMORY_OPEN_READ_WRITE -or $null -ne $config.env_whitelist.GB_MEMORY_OPEN_OUT){throw 'Conflicting OPEN flags must be absent in the full-main parent'}
if($config.extra_env.GB_MEMORY_COMPACT -ne '1' -or $config.extra_env.GB_MEMORY_OUT -ne (Join-Path $runRoot 'output')){throw 'Full-main output/compaction environment mismatch'}
if((Get-FileHash -LiteralPath $config.binary -Algorithm SHA256).Hash -ne $config.binary_sha256){throw 'Frozen diagnostic binary hash mismatch'}
if(Test-Path -LiteralPath $config.extra_env.GB_MEMORY_OUT){throw 'Fresh main output directory already exists'}
function Write-JsonLine([string]$Path,$Value){$line=($Value|ConvertTo-Json -Depth 10 -Compress)+[Environment]::NewLine;[System.IO.File]::AppendAllText($Path,$line,[System.Text.UTF8Encoding]::new($false))}
function Get-InputHashes{[ordered]@{corpus=(Get-FileHash -LiteralPath (Join-Path $config.input_dir 'corpus.f32') -Algorithm SHA256).Hash.ToLowerInvariant();queries=(Get-FileHash -LiteralPath (Join-Path $config.input_dir 'queries.f32') -Algorithm SHA256).Hash.ToLowerInvariant();truth=(Get-FileHash -LiteralPath (Join-Path $config.input_dir 'truth.json') -Algorithm SHA256).Hash.ToLowerInvariant();meta=(Get-FileHash -LiteralPath (Join-Path $config.input_dir 'meta.json') -Algorithm SHA256).Hash.ToLowerInvariant()}}
function Get-HostSample{$cpu=Get-CimInstance -ClassName Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop;$os=Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop;[pscustomobject]@{at_local=(Get-Date).ToString('o');at_utc=(Get-Date).ToUniversalTime().ToString('o');total_cpu_percent=[double]$cpu.PercentProcessorTime;free_physical_bytes=[int64]$os.FreePhysicalMemory*1024}}
function Get-ProcessTreeSnapshot([int[]]$RootProcessIds){$all=@(Get-CimInstance -ClassName Win32_Process -Property ProcessId,ParentProcessId,Name,ExecutablePath -ErrorAction Stop);$depth=@{};$queue=[System.Collections.Generic.Queue[int]]::new();foreach($rootId in $RootProcessIds){if($rootId -gt 0 -and -not $depth.ContainsKey([string]$rootId)){$depth[[string]$rootId]=0;$queue.Enqueue($rootId)}};while($queue.Count -gt 0){$parent=$queue.Dequeue();foreach($entry in $all){$processId=[int]$entry.ProcessId;if([int]$entry.ParentProcessId -eq $parent -and -not $depth.ContainsKey([string]$processId)){$depth[[string]$processId]=$depth[[string]$parent]+1;$queue.Enqueue($processId)}}};$rows=@();foreach($key in $depth.Keys){$id=[int]$key;$wm=$all|Where-Object{[int]$_.ProcessId -eq $id}|Select-Object -First 1;$proc=Get-Process -Id $id -ErrorAction SilentlyContinue;if($null -ne $wm -and $null -ne $proc){$rows+=@([pscustomobject]@{pid=$id;parent_pid=[int]$wm.ParentProcessId;depth=[int]$depth[$key];name=[string]$wm.Name;executable_path=[string]$wm.ExecutablePath;working_set_bytes=[int64]$proc.WorkingSet64;private_bytes=[int64]$proc.PrivateMemorySize64;cpu_seconds=if($null -ne $proc.CPU){[double]$proc.CPU}else{0.0}})}};return @($rows)}
function Stop-OwnedTree([int[]]$RootProcessIds){$tree=@(Get-ProcessTreeSnapshot $RootProcessIds);$ids=@($tree|Sort-Object depth -Descending|ForEach-Object{[int]$_.pid});foreach($id in $ids){try{Stop-Process -Id $id -Force -ErrorAction SilentlyContinue}catch{}};return $ids}
$active=@(Get-CimInstance -ClassName Win32_Process -Property ProcessId,Name,ExecutablePath -ErrorAction Stop|Where-Object{$_.Name -match '^(cargo|rustc|vbench-genesis)(\.exe)?$' -or $_.ExecutablePath -eq $config.binary}|Select-Object ProcessId,Name,ExecutablePath)
if($active.Count -gt 0){throw "Existing build/benchmark process blocks admission: $($active|ConvertTo-Json -Compress)"}
$before=Get-InputHashes;if(($before|ConvertTo-Json -Compress) -ne ($config.expected_input_hashes|ConvertTo-Json -Compress)){throw 'Frozen real input hash mismatch before admission'}
$admissionSamples=@();$admissionPath=Join-Path $runRoot 'host-admission.jsonl'
for($i=0;$i -le 10;$i++){$sample=Get-HostSample;$admissionSamples+=@($sample);Write-JsonLine $admissionPath $sample;if($i -lt 10){Start-Sleep -Seconds 1}}
$cpuAvg=[double](($admissionSamples|Measure-Object total_cpu_percent -Average).Average);$freeMin=[int64](($admissionSamples|Measure-Object free_physical_bytes -Minimum).Minimum)
$admission=[ordered]@{sample_count=$admissionSamples.Count;observed_window_seconds=10;average_total_cpu_percent=$cpuAvg;minimum_free_physical_bytes=$freeMin;minimum_free_gib=[math]::Round($freeMin/1GB,3);cpu_gate_passed=($cpuAvg -lt 20);memory_gate_passed=($freeMin -ge 6GB);active_build_or_benchmark_processes=$active;samples=$admissionSamples}
$admission|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $runRoot 'host-admission.json') -Encoding utf8
if(-not $admission.cpu_gate_passed -or -not $admission.memory_gate_passed){throw 'Host admission failed; candidate was not launched'}
$python=$config.python;$driverStdout=Join-Path $runRoot 'driver.stdout.log';$driverStderr=Join-Path $runRoot 'driver.stderr.log';$timeline=Join-Path $runRoot 'process-tree-timeline.jsonl'
$driver=Start-Process -FilePath $python -ArgumentList @('-u',$driverPath,$configPath) -WindowStyle Hidden -PassThru -WorkingDirectory $runRoot -RedirectStandardOutput $driverStdout -RedirectStandardError $driverStderr
$startLocal=(Get-Date).ToString('o');$clock=[Diagnostics.Stopwatch]::StartNew();$peakWs=0L;$peakPrivate=0L;$timedOut=$false;$rssHit=$false;$killedPids=@();$sampleIndex=0
[ordered]@{driver_pid=$driver.Id;started_at_local=$startLocal;binary=$config.binary;binary_sha256=$config.binary_sha256;input_dir=$config.input_dir;input_hashes_before=$before;output_dir=$config.extra_env.GB_MEMORY_OUT;query_deadline_ms=5000;rss_limit_bytes=2147483648;runtime_cap_seconds=1200;env_whitelist=$config.env_whitelist;extra_env=$config.extra_env;diagnostic_method='Python subprocess.Popen direct stdout/stderr file handles; Win32 process-tree monitor'}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $runRoot 'process-start.json') -Encoding utf8
$benchmarkPid=0
while($true){$driverProc=Get-Process -Id $driver.Id -ErrorAction SilentlyContinue;$pidFile=Join-Path $runRoot 'benchmark-start.json';if(Test-Path -LiteralPath $pidFile){try{$pobj=Get-Content -LiteralPath $pidFile -Raw|ConvertFrom-Json;$benchmarkPid=[int]$pobj.benchmark_pid}catch{}};$roots=@($driver.Id);if($benchmarkPid -gt 0){$roots+=@($benchmarkPid)};$tree=@(Get-ProcessTreeSnapshot $roots);$treeWs=[int64](($tree|Measure-Object working_set_bytes -Sum).Sum);$treePrivate=[int64](($tree|Measure-Object private_bytes -Sum).Sum);if($treeWs -gt $peakWs){$peakWs=$treeWs};if($treePrivate -gt $peakPrivate){$peakPrivate=$treePrivate};$hostSample=Get-HostSample;$record=[ordered]@{at_local=$hostSample.at_local;elapsed_seconds=[math]::Round($clock.Elapsed.TotalSeconds,3);driver_pid=$driver.Id;benchmark_pid=$benchmarkPid;process_tree=$tree;tree_working_set_bytes=$treeWs;tree_private_bytes=$treePrivate;host_cpu_percent=$hostSample.total_cpu_percent;host_free_physical_bytes=$hostSample.free_physical_bytes};Write-JsonLine $timeline $record;if($treeWs -gt 2147483648){$rssHit=$true;$killedPids=Stop-OwnedTree $roots;break};if($clock.Elapsed.TotalSeconds -ge 1200){$timedOut=$true;$killedPids=Stop-OwnedTree $roots;break};$driverAlive=$null -ne $driverProc;$benchProc=$null;if($benchmarkPid -gt 0){$benchProc=Get-Process -Id $benchmarkPid -ErrorAction SilentlyContinue};$treeAlive=($tree.Count -gt 0);if(-not $driverAlive -and -not $treeAlive -and $null -eq $benchProc){break};$sampleIndex++;Start-Sleep -Seconds 1;$driver.Refresh()}
try{Wait-Process -Id $driver.Id -Timeout 30 -ErrorAction SilentlyContinue}catch{};$driver.Refresh();$driverExit=$null;try{$driverExit=$driver.ExitCode}catch{};$clock.Stop();$after=Get-InputHashes;$inputUnchanged=(($after|ConvertTo-Json -Compress) -eq ($config.expected_input_hashes|ConvertTo-Json -Compress));$driverStatus=$null;$driverStatusPath=Join-Path $runRoot 'driver-status.json';if(Test-Path -LiteralPath $driverStatusPath){$driverStatus=Get-Content -LiteralPath $driverStatusPath -Raw|ConvertFrom-Json};$candidateExit=$null;if($null -ne $driverStatus){$candidateExit=$driverStatus.exit_code};$final=[ordered]@{status=if($timedOut){'timed_out'}elseif($rssHit){'rss_guard_killed'}elseif($driverExit -eq 0){'complete'}else{'driver_or_benchmark_failed'};driver_pid=$driver.Id;benchmark_pid=$benchmarkPid;driver_exit_code=$driverExit;candidate_exit_code=$candidateExit;timed_out=$timedOut;rss_limit_hit=$rssHit;killed_pids=$killedPids;elapsed_seconds=[math]::Round($clock.Elapsed.TotalSeconds,3);peak_process_tree_working_set_bytes=$peakWs;peak_process_tree_private_bytes=$peakPrivate;query_deadline_ms=5000;rss_limit_bytes=2147483648;runtime_cap_seconds=1200;input_hashes_before=$before;input_hashes_after=$after;input_unchanged=$inputUnchanged;admission=$admission;driver_status=$driverStatus}
$final|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $runRoot 'controller-status.json') -Encoding utf8
Write-Output ($final|ConvertTo-Json -Compress -Depth 8)
